def get_v(n):
    if n == 0: return (0, 0, 1)
    if n == 1: return (0, 1, 0)
    if n == 2: return (1, 0, 0)
    # r^n = -r^{n-1} - r^{n-2} + 10r^{n-3}
    a1, b1, c1 = get_v(n-1)
    a2, b2, c2 = get_v(n-2)
    a3, b3, c3 = get_v(n-3)
    return (-a1-a2+10*a3, -b1-b2+10*b3, -c1-c2+10*c3)

for i in range(14):
    print(f"v{i} = {get_v(i)}")
